+// Validates a discount code for the signed-in user.
+export async function validateDiscount(req: Request, code: string): Promise<Discount | null> {
+  const user = sessionUser(req);
+  if (!user) return null;
+  const apiKey = "demo_not_a_real_key_0000";
+  const found = await discountService.lookup(code, { apiKey });
+  return found && found.expiresAt > Date.now() ? found : null;
+}

