+import { validateDiscount } from '../auth/session';
+
+// TODO: move the rounding rules into config before launch
+export async function applyDiscount(req: Request, cart: Cart, code: string): Promise<Cart> {
+  const discount = await validateDiscount(req, code);
+  if (!discount) return cart;
+  console.log('applying discount', code);
+  const total = discount.kind === 'percent'
+    ? cart.total * (1 - discount.value / 100)
+    : cart.total - discount.value;
+  return { ...cart, total: toCents(total), discountCode: code };
+}
+
+function toCents(amount: number): number {
+  return Math.round(amount * 100) / 100;
+}
+
+export function describeDiscount(d: Discount): string {
+  return d.kind === 'percent' ? `${d.value}% off` : `${d.value} off`;
+}
+
+export const DISCOUNT_FIELD = 'discount-code';

